/**
 * Query is the read side of the livestock registry.
 *
 * Open to the public on this chain, deliberately. A certificate a buyer cannot
 * check without trusting the issuer is a certificate that moves the trust
 * rather than establishing it, and the whole point of the exercise is that a
 * stranger with a phone can verify what they are being sold.
 *
 * What is NOT here is as deliberate: no endpoint lists a keeper's holdings by
 * name, and none returns a herd's location together with its keeper's
 * identity. A registry of who owns livestock and exactly where it grazes is a
 * shopping list for cattle raiders, and publishing it would defeat the theft
 * argument the registry is built on.
 */
export interface Query {
  /** Params returns the module parameters. */
  Params(request: QueryParamsRequest): Promise<QueryParamsResponse>;
  /** Authorities lists the registry offices. */
  Authorities(request: QueryAuthoritiesRequest): Promise<QueryAuthoritiesResponse>;
  /**
   * Agents lists the accredited people an office answers for, struck-off ones
   * included: "was this person accredited when they signed" is a question
   * about the past.
   */
  Agents(request: QueryAgentsRequest): Promise<QueryAgentsResponse>;
  /** Herd returns one herd by its chain id. */
  Herd(request: QueryHerdRequest): Promise<QueryHerdResponse>;
  /**
   * HerdByRef returns one herd by the registry's own reference, which is what
   * an officer holding a paper file actually has in front of them.
   */
  HerdByRef(request: QueryHerdByRefRequest): Promise<QueryHerdResponse>;
  /** Animal returns one animal by its chain id. */
  Animal(request: QueryAnimalRequest): Promise<QueryAnimalResponse>;
  /**
   * AnimalByNationalID is the certificate lookup: the identifier printed on
   * the document, resolved to the record it refers to.
   */
  AnimalByNationalID(request: QueryAnimalByNationalIDRequest): Promise<QueryAnimalResponse>;
  /**
   * AnimalByTag resolves a transponder code read in the field. This is the
   * query an agent with a reader makes, and the one that answers "whose animal
   * is this".
   */
  AnimalByTag(request: QueryAnimalByTagRequest): Promise<QueryAnimalResponse>;
  /**
   * Pedigree walks the line upward from one animal.
   *
   * The endpoint that the free-text certificate cannot have. Depth is bounded
   * by the caller and by the module, because an unbounded walk over a graph
   * somebody else populated is a denial of service with a polite name.
   */
  Pedigree(request: QueryPedigreeRequest): Promise<QueryPedigreeResponse>;
  /** Animals lists the animals in one herd. */
  Animals(request: QueryAnimalsRequest): Promise<QueryAnimalsResponse>;
  /**
   * HealthEvents lists what a herd has been treated for, which is the
   * difference between coverage and a count of doses.
   */
  HealthEvents(request: QueryHealthEventsRequest): Promise<QueryHealthEventsResponse>;
  /** Transfer returns one transfer. */
  Transfer(request: QueryTransferRequest): Promise<QueryTransferResponse>;
  /**
   * TransfersByAnimal is the provenance of one animal: every supervised
   * handover it has been through, including the ones that were objected to.
   */
  TransfersByAnimal(request: QueryTransfersByAnimalRequest): Promise<QueryTransfersResponse>;
}

